sp_widget.client_script:
api.controller = function($window) {
  var c = this;

  c.loading = false;
  c.cancelling = false;

  c.getStatusClass = function(status) {
    var map = {
      'pending': 'label-warning',
      'approved': 'label-info',
      'checked_in': 'label-success',
      'checked_out': 'label-default',
      'cancelled': 'label-danger',
      'rejected': 'label-danger'
    };
    return map[status] || 'label-default';
  };

  c.getStatusLabel = function(status) {
    var map = {
      'pending': 'Pending',
      'approved': 'Approved',
      'checked_in': 'Checked In',
      'checked_out': 'Checked Out',
      'cancelled': 'Cancelled',
      'rejected': 'Rejected'
    };
    return map[status] || status;
  };

  c.getApprovalMessage = function() {
    if (!c.data.visit) return '';
    var status = c.data.visit.status;
    if (status === 'pending') return 'Awaiting manager approval';
    if (status === 'approved') return 'Approved by manager';
    if (status === 'rejected') return 'Rejected by manager';
    return '';
  };

  c.getApprovalIcon = function() {
    if (!c.data.visit) return '';
    var status = c.data.visit.status;
    if (status === 'pending') return 'glyphicon-time';
    if (status === 'approved') return 'glyphicon-ok-circle';
    if (status === 'rejected') return 'glyphicon-remove-circle';
    return 'glyphicon-info-sign';
  };

  c.viewDetail = function(visit) {
    $window.location.href = '?id=' + c.data.pageId + '&sys_id=' + visit.sys_id;
  };

  c.goBack = function() {
    $window.location.href = '?id=' + c.data.pageId;
  };

  c.cancelVisit = function() {
    if (!c.data.visit || c.data.visit.status !== 'pending') return;
    c.cancelling = true;
    c.server.get({ action: 'cancel', visit_sys_id: c.data.visit.sys_id }).then(
      function(r) {
        c.data = r.data;
        c.cancelling = false;
      },
      function() {
        c.cancelling = false;
      }
    );
  };
};

sp_widget.css:
/* ── Flush panel body for tables ────────────────────────── */
.sp-card-body-flush {
  padding: 0;
  overflow: hidden;
}

/* ── Table styling (css.md Section 10) ─────────────────── */
.sp-th {
  font-size: 12px;
  font-weight: 600;
  color: $text-muted;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 12px 16px;
  border-bottom: 2px solid $border-tertiary;
  background: $background-secondary;
}

.sp-td {
  font-size: $font-size-small;
  padding: 12px 16px;
  color: $text-color;
  border-bottom: 1px solid $border-tertiary;
  vertical-align: middle;
}

.sp-clickable-row {
  cursor: pointer;
  &:hover {
    background: $background-secondary;
  }
}

/* ── Buttons (css.md Section 9) ────────────────────────── */
.sp-btn-secondary {
  background: $background-primary;
  border: 1px solid $border-tertiary;
  color: $text-color;
  height: 44px;
  padding: 0 20px;
  border-radius: $border-radius-base;
  font-size: $font-size-base;
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 16px;
  &:hover {
    background: $background-secondary;
  }
}

.sp-btn-danger {
  height: 44px;
  padding: 0 20px;
  border-radius: $border-radius-base;
  font-size: $font-size-base;
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  border: none;
  background: $brand-danger;
  color: $btn-primary-color;
  &:hover:not(:disabled) {
    background: darken($brand-danger, 8%);
  }
  &:disabled {
    opacity: 0.55;
    cursor: not-allowed;
  }
}

.sp-btn-group {
  display: flex;
  gap: 8px;
  align-items: center;
  margin-top: 24px;
  flex-wrap: wrap;
}

/* ── Empty state (css.md Section 13) ───────────────────── */
.sp-empty-state {
  padding: 64px 24px;
}

.sp-empty-icon {
  font-size: 48px;
  margin-bottom: 16px;
  display: block;
  opacity: 0.35;
  color: $text-muted;
}

.sp-empty-title {
  font-size: $font-size-large;
  font-weight: 600;
  color: $text-color;
  margin-bottom: 8px;
}

/* ── Approval status panel (custom, non-sp prefix) ─────── */
.approval-panel .panel-body {
  padding: 32px 24px;
}

.approval-icon {
  font-size: 48px;
  margin-bottom: 16px;
  display: block;
}

.approval-status-text {
  font-size: 22px;
  font-weight: 600;
  margin: 0 0 8px;
}

/* ── Detail list styling ───────────────────────────────── */
.detail-list dt {
  margin-top: 12px;
  font-size: $font-size-small;
}

.detail-list dd {
  font-size: $font-size-base;
  color: $text-color;
  margin-bottom: 4px;
}

.detail-list dt:first-child {
  margin-top: 0;
}

/* ── Theme-aware Bootstrap label overrides ──────────────── */
.label-success {
  background-color: $brand-success;
}
.label-warning {
  background-color: $brand-warning;
}
.label-danger {
  background-color: $brand-danger;
}
.label-info {
  background-color: $brand-info;
}

/* ── Spin animation (css.md Section 9) ─────────────────── */
@keyframes sp-spin {
  to { transform: rotate(360deg); }
}
.sp-spin {
  animation: sp-spin 0.8s linear infinite;
}

sp_widget.script:
(function() {
  data.visits = [];
  data.visit = null;
  data.view = 'list';
  data.message = '';
  data.success = false;
  data.pageId = 'x_1085196_visita_0_my_visits';

  try {
    // Handle cancel action
    if (input && input.action === 'cancel' && input.visit_sys_id) {
      var cancelGr = new GlideRecord('x_1085196_visita_0_visit');
      if (cancelGr.get(input.visit_sys_id)) {
        if (cancelGr.getValue('status') === 'pending' &&
            cancelGr.getValue('requested_by') === gs.getUserID()) {
          cancelGr.setValue('status', 'cancelled');
          cancelGr.update();
          data.success = true;
          data.message = 'Visit request cancelled successfully.';
        } else {
          data.message = 'Unable to cancel this visit request.';
        }
      }
      // Fall through to re-fetch updated data
    }

    var sysId = $sp.getParameter('sys_id');

    if (sysId) {
      // Detail view
      data.view = 'detail';
      var visitGr = new GlideRecord('x_1085196_visita_0_visit');
      if (visitGr.get(sysId)) {
        // Verify the visit belongs to current user
        if (visitGr.getValue('requested_by') === gs.getUserID()) {
          data.visit = {
            sys_id: visitGr.getUniqueValue(),
            number: visitGr.getValue('number'),
            visitor_name: visitGr.getValue('visitor_name'),
            visitor_email: visitGr.getValue('visitor_email'),
            visitor_phone: visitGr.getValue('visitor_phone'),
            visitor_company: visitGr.getValue('visitor_company'),
            host: visitGr.getDisplayValue('host') + '',
            visit_date: visitGr.getDisplayValue('visit_date') + '',
            status: visitGr.getValue('status'),
            purpose: visitGr.getValue('purpose'),
            notes: visitGr.getValue('notes'),
            requested_by: visitGr.getDisplayValue('requested_by') + ''
          };
        }
      }
    } else {
      // List view — user's own visits
      data.view = 'list';
      var gr = new GlideRecord('x_1085196_visita_0_visit');
      gr.addQuery('requested_by', gs.getUserID());
      gr.orderByDesc('sys_created_on');
      gr.setLimit(100);
      gr.query();
      while (gr.next()) {
        data.visits.push({
          sys_id: gr.getUniqueValue(),
          number: gr.getValue('number'),
          visitor_name: gr.getValue('visitor_name'),
          host: gr.getDisplayValue('host') + '',
          visit_date: gr.getDisplayValue('visit_date') + '',
          status: gr.getValue('status'),
          purpose: gr.getValue('purpose')
        });
      }
    }
  } catch (e) {
    gs.error('My Visit Requests widget error: ' + e.message);
    data.message = 'An error occurred loading visit data.';
  }
})();
